// Transaction types: BTC, ETH, wire, cash, USDT
const TX_TYPES = ["BTC","ETH","WIRE","CASH","USDT"];
const TX_COLORS = { BTC:"#f7931a", ETH:"#627eea", WIRE:"#6496c8", CASH:"#00e87a", USDT:"#26a17b" };

function buildEarthTexture() {
  const W = 4096, H = 2048;
  const canvas = document.createElement("canvas");
  canvas.width = W; canvas.height = H;
  const ctx = canvas.getContext("2d");

  // Deep ocean — site dark palette
  const ocean = ctx.createLinearGradient(0, 0, 0, H);
  ocean.addColorStop(0,   "#010510");
  ocean.addColorStop(0.3, "#020a1a");
  ocean.addColorStop(0.5, "#030f24");
  ocean.addColorStop(0.7, "#020a1a");
  ocean.addColorStop(1,   "#010510");
  ctx.fillStyle = ocean;
  ctx.fillRect(0, 0, W, H);

  // Subtle ocean depth shimmer
  for (let i = 0; i < 40; i++) {
    const x = Math.random()*W, y = Math.random()*H;
    const g = ctx.createRadialGradient(x,y,0,x,y,120+Math.random()*160);
    g.addColorStop(0,"rgba(30,70,130,0.05)");
    g.addColorStop(1,"rgba(0,0,0,0)");
    ctx.fillStyle = g; ctx.fillRect(0,0,W,H);
  }

  const px = (lon, lat) => [((lon+180)/360)*W, ((90-lat)/180)*H];

  // Draw all land in one pass — fill then stroke
  // Pass 1: fill all land polygons
  LAND_POLYS.forEach((poly) => {
    if (poly.length < 3) return;
    ctx.beginPath();
    poly.forEach(([lon, lat], i) => {
      const [x, y] = px(lon, lat);
      i === 0 ? ctx.moveTo(x, y) : ctx.lineTo(x, y);
    });
    ctx.closePath();

    // Latitude-based colour: polar=grey-blue, temperate=steel, tropical=darker teal
    const avgLat = poly.reduce((s,[,la])=>s+la,0)/poly.length;
    let fill;
    if (Math.abs(avgLat) > 65)      fill = "#1e2d42";
    else if (Math.abs(avgLat) > 45) fill = "#162438";
    else if (Math.abs(avgLat) > 25) fill = "#122033";
    else                            fill = "#101d30";
    ctx.fillStyle = fill;
    ctx.fill();
  });

  // Pass 2: coastline glow over all land
  ctx.lineWidth = 0.8;
  ctx.strokeStyle = "rgba(100,155,200,0.5)";
  LAND_POLYS.forEach((poly) => {
    if (poly.length < 3) return;
    ctx.beginPath();
    poly.forEach(([lon, lat], i) => {
      const [x, y] = px(lon, lat);
      i === 0 ? ctx.moveTo(x, y) : ctx.lineTo(x, y);
    });
    ctx.closePath();
    ctx.stroke();
  });

  // ── GRID LAYER 1: Fine 10-degree grid (behind everything) ──
  ctx.strokeStyle = "rgba(70,110,160,0.07)";
  ctx.lineWidth = 0.5;
  for (let lat = -80; lat <= 80; lat += 10) {
    const [,y] = px(0, lat);
    ctx.beginPath(); ctx.moveTo(0,y); ctx.lineTo(W,y); ctx.stroke();
  }
  for (let lon = -170; lon <= 180; lon += 10) {
    ctx.beginPath();
    for (let lat = -90; lat <= 90; lat += 1) {
      const [x,y] = px(lon, lat);
      lat === -90 ? ctx.moveTo(x,y) : ctx.lineTo(x,y);
    }
    ctx.stroke();
  }

  // ── GRID LAYER 2: Major 30-degree lines (slightly brighter) ──
  ctx.strokeStyle = "rgba(100,150,200,0.12)";
  ctx.lineWidth = 0.8;
  for (let lat = -60; lat <= 60; lat += 30) {
    const [,y] = px(0, lat);
    ctx.beginPath(); ctx.moveTo(0,y); ctx.lineTo(W,y); ctx.stroke();
  }
  for (let lon = -150; lon <= 180; lon += 30) {
    ctx.beginPath();
    for (let lat = -90; lat <= 90; lat += 1) {
      const [x,y] = px(lon, lat);
      lat === -90 ? ctx.moveTo(x,y) : ctx.lineTo(x,y);
    }
    ctx.stroke();
  }

  // ── COUNTRY BORDERS ──
  ctx.strokeStyle = "rgba(150,200,255,0.45)";
  ctx.lineWidth = 1.2;
  ctx.setLineDash([]);
  COUNTRY_BORDERS.forEach((line) => {
    if (line.length < 2) return;
    ctx.beginPath();
    line.forEach(([lon, lat], i) => {
      const [x, y] = px(lon, lat);
      i === 0 ? ctx.moveTo(x, y) : ctx.lineTo(x, y);
    });
    ctx.stroke();
  });

  // Polar ice caps
  const ice = (yC, h) => {
    const g = ctx.createLinearGradient(0, yC-h, 0, yC+h);
    g.addColorStop(0, "rgba(180,210,240,0.7)");
    g.addColorStop(0.5, "rgba(140,175,215,0.35)");
    g.addColorStop(1, "rgba(100,140,190,0)");
    ctx.fillStyle = g; ctx.fillRect(0, yC-h, W, h*2);
  };
  ice(0, 60); ice(H, 80);

  return canvas;
}

// Draw a mini crypto/transaction icon onto a canvas and return as texture
function makeIconTexture(THREE, type) {
  const s = 64;
  const c = document.createElement("canvas");
  c.width = s; c.height = s;
  const ctx = c.getContext("2d");
  const col = TX_COLORS[type];

  // Glow bg — skip for symbol-only types
  if (type !== "BTC" && type !== "USDT") {
    const g = ctx.createRadialGradient(s/2,s/2,0, s/2,s/2,s/2);
    g.addColorStop(0, col+"66"); g.addColorStop(1, "rgba(0,0,0,0)");
    ctx.fillStyle = g; ctx.fillRect(0,0,s,s);
  }

  ctx.fillStyle = col;
  ctx.strokeStyle = col;

  const cx = s/2, cy = s/2;

  if (type === "BTC") {
    ctx.font = `bold ${s*0.48}px serif`;
    ctx.textAlign = "center"; ctx.textBaseline = "middle";
    ctx.fillText("₿", cx, cy);
  } else if (type === "ETH") {
    // Ethereum diamond — two triangles
    ctx.lineWidth = 1.5;
    // Top diamond
    ctx.beginPath();
    ctx.moveTo(cx, cy - 18);
    ctx.lineTo(cx + 12, cy - 2);
    ctx.lineTo(cx, cy + 4);
    ctx.lineTo(cx - 12, cy - 2);
    ctx.closePath();
    ctx.fill();
    // Bottom diamond (smaller)
    ctx.globalAlpha = 0.6;
    ctx.beginPath();
    ctx.moveTo(cx, cy + 18);
    ctx.lineTo(cx + 12, cy + 2);
    ctx.lineTo(cx, cy - 4);
    ctx.lineTo(cx - 12, cy + 2);
    ctx.closePath();
    ctx.fill();
    ctx.globalAlpha = 1;
  } else if (type === "WIRE") {
    // Arrow left-right
    ctx.lineWidth = 3;
    ctx.lineCap = "round";
    ctx.beginPath(); ctx.moveTo(cx-14,cy); ctx.lineTo(cx+14,cy); ctx.stroke();
    ctx.beginPath(); ctx.moveTo(cx+8,cy-6); ctx.lineTo(cx+14,cy); ctx.lineTo(cx+8,cy+6); ctx.stroke();
    ctx.beginPath(); ctx.moveTo(cx-8,cy-6); ctx.lineTo(cx-14,cy); ctx.lineTo(cx-8,cy+6); ctx.stroke();
  } else if (type === "CASH") {
    ctx.font = `bold ${s*0.42}px Arial`;
    ctx.textAlign = "center"; ctx.textBaseline = "middle";
    ctx.fillText("$", cx, cy);
  } else if (type === "USDT") {
    ctx.font = `bold ${s*0.48}px serif`;
    ctx.textAlign = "center"; ctx.textBaseline = "middle";
    ctx.fillText("₮", cx, cy);
  }

  return new THREE.CanvasTexture(c);
}

export default function HeroGlobe() {
  const mountRef = useRef(null);
  const [ready, setReady] = useState(false);

  useEffect(() => {
    let renderer, raf;
    let cleanupFn = null;

    const init = async () => {
      const THREE = await import("three");
      const el = mountRef.current;
      if (!el) return;

      const W = el.offsetWidth || 560;
      const H = el.offsetHeight || 560;

      renderer = new THREE.WebGLRenderer({ antialias: true, alpha: true });
      renderer.setSize(W, H);
      renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
      renderer.setClearColor(0x000000, 0);
      el.appendChild(renderer.domElement);

      const scene = new THREE.Scene();
      const camera = new THREE.PerspectiveCamera(35, W/H, 0.1, 100);
      camera.position.set(0, 0, 5.0);
      const R = 1.5;

      // Earth
      const earthTex = new THREE.CanvasTexture(buildEarthTexture());
      const globe = new THREE.Mesh(
        new THREE.SphereGeometry(R, 64, 64),
        new THREE.MeshPhongMaterial({ map: earthTex, specular: new THREE.Color(0x1a3a6a), shininess: 30 })
      );
      scene.add(globe);

      // Atmosphere — dark blue halo
      scene.add(new THREE.Mesh(
        new THREE.SphereGeometry(R*1.10, 32, 32),
        new THREE.MeshBasicMaterial({ color:0x0a2060, transparent:true, opacity:0.10, side:THREE.BackSide })
      ));
      // Rim glow matching site accent
      scene.add(new THREE.Mesh(
        new THREE.SphereGeometry(R*1.04, 32, 32),
        new THREE.MeshBasicMaterial({ color:0x3a6090, transparent:true, opacity:0.05, side:THREE.FrontSide })
      ));

      // Hub cities
      const CITIES = [
        // --- Americas (0-25) ---
        [40.71,-74.01],   // 0  NYC
        [43.65,-79.38],   // 1  Toronto
        [34.05,-118.24],  // 2  Los Angeles
        [41.85,-87.65],   // 3  Chicago
        [29.76,-95.37],   // 4  Houston
        [25.77,-80.19],   // 5  Miami
        [37.77,-122.42],  // 6  San Francisco
        [32.78,-96.80],   // 7  Dallas
        [42.36,-71.06],   // 8  Boston
        [45.50,-73.57],   // 9  Montreal
        [49.28,-123.12],  // 10 Vancouver
        [-23.55,-46.63],  // 11 Sao Paulo
        [-34.60,-58.38],  // 12 Buenos Aires
        [4.71,-74.07],    // 13 Bogota
        [19.43,-99.13],   // 14 Mexico City
        [-12.04,-77.03],  // 15 Lima
        // --- Europe (16-24) ---
        [51.51,-0.13],    // 16 London
        [48.85,2.35],     // 17 Paris
        [52.52,13.40],    // 18 Berlin
        [47.38,8.54],     // 19 Zurich
        [41.90,12.49],    // 20 Rome
        [40.42,-3.70],    // 21 Madrid
        [59.33,18.07],    // 22 Stockholm
        [50.08,14.44],    // 23 Prague
        [48.21,16.37],    // 24 Vienna
        // --- Middle East / Africa (25-31) ---
        [25.20,55.27],    // 25 Dubai
        [24.69,46.72],    // 26 Riyadh
        [30.04,31.24],    // 27 Cairo
        [-1.29,36.82],    // 28 Nairobi
        [6.52,3.38],      // 29 Lagos
        [-26.20,28.04],   // 30 Johannesburg
        [33.89,35.50],    // 31 Beirut
        // --- Asia / Pacific (32-44) ---
        [55.75,37.62],    // 32 Moscow
        [19.08,72.88],    // 33 Mumbai
        [28.61,77.21],    // 34 New Delhi
        [31.23,121.47],   // 35 Shanghai
        [22.32,114.17],   // 36 Hong Kong
        [1.35,103.82],    // 37 Singapore
        [35.69,139.69],   // 38 Tokyo
        [37.57,126.98],   // 39 Seoul
        [13.75,100.52],   // 40 Bangkok
        [3.14,101.69],    // 41 Kuala Lumpur
        [-6.21,106.85],   // 42 Jakarta
        [-33.87,151.21],  // 43 Sydney
        [-37.81,144.96],  // 44 Melbourne
      ];

      const ll2v = (lat, lon, r) => {
        const phi = (90-lat)*(Math.PI/180), th = (lon+180)*(Math.PI/180);
        return new THREE.Vector3(-r*Math.sin(phi)*Math.cos(th), r*Math.cos(phi), r*Math.sin(phi)*Math.sin(th));
      };

      // City pulse dots (small, site-green)
      // Major financial hubs get bigger/brighter nodes
      const MAJOR_HUBS = new Set([0,1,2,3,4,6,7,10,13,14,16,19,25,32,33,35,36,37,38,39,43]);

      const cityObjs = CITIES.map(([lat,lon], i) => {
        const pos = ll2v(lat, lon, R*1.013);
        const isMajor = MAJOR_HUBS.has(i);
        const nodeColor = isMajor ? 0x00e87a : 0x6496c8;
        const nodeSize  = isMajor ? 0.028 : 0.016;

        // Core dot
        const dot = new THREE.Mesh(
          new THREE.SphereGeometry(nodeSize, 10, 10),
          new THREE.MeshBasicMaterial({ color: nodeColor, transparent:true, opacity:1 })
        );
        dot.position.copy(pos);

        // Inner glow ring
        const ring1 = new THREE.Mesh(
          new THREE.RingGeometry(nodeSize*1.4, nodeSize*2.2, 24),
          new THREE.MeshBasicMaterial({ color: nodeColor, transparent:true, opacity:0.6, side:THREE.DoubleSide })
        );
        ring1.position.copy(pos); ring1.lookAt(new THREE.Vector3(0,0,0));

        // Outer pulse ring (major hubs only)
        let ring2 = null;
        if (isMajor) {
          ring2 = new THREE.Mesh(
            new THREE.RingGeometry(nodeSize*3, nodeSize*4, 24),
            new THREE.MeshBasicMaterial({ color: nodeColor, transparent:true, opacity:0.25, side:THREE.DoubleSide })
          );
          ring2.position.copy(pos); ring2.lookAt(new THREE.Vector3(0,0,0));
          scene.add(ring2);
        }

        scene.add(dot); scene.add(ring1);
        return { pos, dot, ring1, ring2, phase:(i/CITIES.length)*Math.PI*2, isMajor };
      });

      // Arc definitions with transaction types
      const ARC_DEFS = [
        // ── NORTH AMERICA INTRA ─────────────────────────────────────
        [0,8,"BTC",0.006],   // NYC-Boston
        [0,3,"ETH",0.008],   // NYC-Chicago
        [0,5,"WIRE",0.005],  // NYC-Miami
        [0,9,"USDT",0.006],  // NYC-Montreal
        [0,1,"CASH",0.006],  // NYC-Toronto
        [0,2,"BTC",0.004],   // NYC-LA
        [0,6,"ETH",0.007],   // NYC-SF
        [2,6,"BTC",0.007],   // LA-SF
        [2,4,"WIRE",0.005],  // LA-Houston
        [2,7,"USDT",0.006],  // LA-Dallas
        [6,10,"ETH",0.009],  // SF-Vancouver
        [6,3,"BTC",0.005],   // SF-Chicago
        [3,4,"CASH",0.006],  // Chicago-Houston
        [3,7,"ETH",0.008],   // Chicago-Dallas
        [3,1,"WIRE",0.006],  // Chicago-Toronto
        [4,5,"USDT",0.007],  // Houston-Miami
        [4,7,"BTC",0.007],   // Houston-Dallas
        [8,9,"ETH",0.009],   // Boston-Montreal
        [9,10,"WIRE",0.006], // Montreal-Vancouver
        [10,1,"BTC",0.006],  // Vancouver-Toronto
        [1,9,"USDT",0.007],  // Toronto-Montreal
        [14,2,"CASH",0.005], // MexCity-LA
        [14,4,"BTC",0.005],  // MexCity-Houston
        // ── SOUTH AMERICA INTRA ────────────────────────────────────
        [11,12,"BTC",0.005], // SP-BuenosAires
        [11,13,"ETH",0.007], // SP-Bogota
        [11,15,"WIRE",0.005],// SP-Lima
        [13,14,"USDT",0.005],// Bogota-MexCity
        // ── EUROPE INTRA ───────────────────────────────────────────
        [16,17,"BTC",0.007], // London-Paris
        [16,18,"ETH",0.008], // London-Berlin
        [16,19,"WIRE",0.006],// London-Zurich
        [16,21,"USDT",0.006],// London-Madrid
        [17,18,"CASH",0.007],// Paris-Berlin
        [17,19,"BTC",0.007], // Paris-Zurich
        [17,20,"ETH",0.008], // Paris-Rome
        [18,22,"WIRE",0.006],// Berlin-Stockholm
        [18,23,"USDT",0.007],// Berlin-Prague
        [19,24,"BTC",0.007], // Zurich-Vienna
        [20,21,"ETH",0.008], // Rome-Madrid
        [22,23,"CASH",0.006],// Stockholm-Prague
        // ── MIDDLE EAST / AFRICA INTRA ─────────────────────────────
        [25,26,"BTC",0.006], // Dubai-Riyadh
        [25,27,"ETH",0.008], // Dubai-Cairo
        [25,31,"WIRE",0.006],// Dubai-Beirut
        [27,28,"USDT",0.005],// Cairo-Nairobi
        [28,29,"BTC",0.005], // Nairobi-Lagos
        [28,30,"ETH",0.007], // Nairobi-Johannesburg
        [29,30,"WIRE",0.005],// Lagos-Johannesburg
        // ── ASIA INTRA ─────────────────────────────────────────────
        [32,35,"BTC",0.005], // Moscow-Shanghai
        [33,34,"ETH",0.008], // Mumbai-Delhi
        [33,37,"WIRE",0.005],// Mumbai-Singapore
        [34,35,"USDT",0.005],// Delhi-Shanghai
        [35,36,"BTC",0.007], // Shanghai-HongKong
        [35,38,"ETH",0.008], // Shanghai-Tokyo
        [35,39,"WIRE",0.006],// Shanghai-Seoul
        [36,37,"CASH",0.007],// HK-Singapore
        [36,38,"BTC",0.006], // HK-Tokyo
        [37,40,"ETH",0.009], // Singapore-Bangkok
        [37,41,"WIRE",0.007],// Singapore-KL
        [37,42,"USDT",0.006],// Singapore-Jakarta
        [38,39,"BTC",0.007], // Tokyo-Seoul
        [40,41,"ETH",0.009], // Bangkok-KL
        [43,44,"WIRE",0.007],// Sydney-Melbourne
        [43,37,"BTC",0.004], // Sydney-Singapore
        // ── TRANSATLANTIC ──────────────────────────────────────────
        [0,16,"BTC",0.003],  // NYC-London
        [0,17,"ETH",0.005],  // NYC-Paris
        [8,16,"WIRE",0.003], // Boston-London
        [5,16,"USDT",0.003], // Miami-London
        [11,16,"BTC",0.003], // SP-London
        [11,17,"ETH",0.005], // SP-Paris
        [12,19,"WIRE",0.003],// BuenosAires-Zurich
        [13,17,"CASH",0.003],// Bogota-Paris
        [1,16,"USDT",0.003], // Toronto-London
        // ── TRANS-PACIFIC ──────────────────────────────────────────
        [6,38,"BTC",0.003],  // SF-Tokyo
        [6,39,"ETH",0.005],  // SF-Seoul
        [6,35,"WIRE",0.003], // SF-Shanghai
        [2,38,"USDT",0.003], // LA-Tokyo
        [2,36,"BTC",0.003],  // LA-HongKong
        [10,38,"ETH",0.005], // Vancouver-Tokyo
        [43,6,"WIRE",0.003], // Sydney-SF
        [43,2,"BTC",0.003],  // Sydney-LA
        // ── NA TO MIDDLE EAST / ASIA ───────────────────────────────
        [0,25,"BTC",0.003],  // NYC-Dubai
        [0,33,"ETH",0.005],  // NYC-Mumbai
        [2,25,"WIRE",0.003], // LA-Dubai
        [16,25,"USDT",0.003],// London-Dubai
        [16,33,"BTC",0.003], // London-Mumbai
        [16,32,"ETH",0.005], // London-Moscow
        [19,25,"WIRE",0.003],// Zurich-Dubai
        // ── AFRICA TO WORLD ────────────────────────────────────────
        [28,16,"BTC",0.003], // Nairobi-London
        [29,16,"ETH",0.005], // Lagos-London
        [30,25,"WIRE",0.003],// Johannesburg-Dubai
        [27,25,"BTC",0.004], // Cairo-Dubai
        // ── EUROPE TO ASIA ─────────────────────────────────────────
        [16,35,"BTC",0.003], // London-Shanghai
        [16,37,"ETH",0.005], // London-Singapore
        [17,33,"WIRE",0.003],// Paris-Mumbai
        [19,25,"USDT",0.003],// Zurich-Dubai
        [32,35,"CASH",0.003],// Moscow-Shanghai
        [32,38,"BTC",0.003], // Moscow-Tokyo
      ];

      // Pre-build icon textures
      const iconTextures = {};
      TX_TYPES.forEach(t => { iconTextures[t] = makeIconTexture(THREE, t); });

      const buildArc = (iA, iB) => {
        const vA = ll2v(CITIES[iA][0], CITIES[iA][1], R*1.01);
        const vB = ll2v(CITIES[iB][0], CITIES[iB][1], R*1.01);
        const mid = vA.clone().add(vB).multiplyScalar(0.5);
        mid.normalize().multiplyScalar(R + vA.distanceTo(vB)*0.55 + 0.1);
        return Array.from({length:81},(_,k)=>{
          const t=k/80;
          return new THREE.Vector3()
            .addScaledVector(vA,(1-t)*(1-t)).addScaledVector(mid,2*t*(1-t)).addScaledVector(vB,t*t);
        });
      };

      const arcs = ARC_DEFS.map(([a,b,type,speed],i) => {
        const pts = buildArc(a, b);
        const col = new THREE.Color(TX_COLORS[type]);
        const lm = new THREE.LineBasicMaterial({ color:col, transparent:true, opacity:0 });
        const lg = new THREE.BufferGeometry().setFromPoints(pts.slice(0,2));
        const line = new THREE.Line(lg, lm);
        scene.add(line);

        // Icon sprite on the head
        const sprite = new THREE.Sprite(
          new THREE.SpriteMaterial({ map:iconTextures[type], transparent:true, opacity:0, sizeAttenuation:true })
        );
        sprite.scale.set(0.07, 0.07, 1);
        scene.add(sprite);

        // Particle trail
        const trail = Array.from({length:6},(_,j)=>{
          const tm = new THREE.MeshBasicMaterial({ color:col, transparent:true, opacity:0 });
          const td = new THREE.Mesh(new THREE.SphereGeometry(0.01*(1-j/6),4,4), tm);
          scene.add(td);
          return {mesh:td, mat:tm};
        });

        return { pts, line, lineGeo:lg, lineMat:lm, sprite, spriteMat:sprite.material, trail, progress:-(i*0.11)%1, speed, type };
      });

      // Stars
      const sp = new Float32Array(1200*3);
      for(let i=0;i<1200*3;i++) sp[i]=(Math.random()-0.5)*20;
      const sg = new THREE.BufferGeometry();
      sg.setAttribute("position", new THREE.BufferAttribute(sp,3));
      scene.add(new THREE.Points(sg, new THREE.PointsMaterial({color:0x4466aa,size:0.012,transparent:true,opacity:0.35})));

      // Lighting — darker, cooler, matching site
      scene.add(new THREE.AmbientLight(0x1a2a44, 1.2));
      const sun = new THREE.DirectionalLight(0x6080b0, 2.5);
      sun.position.set(5,3,4); scene.add(sun);
      const fill = new THREE.PointLight(0x001830, 0.6, 20);
      fill.position.set(-5,-3,-3); scene.add(fill);
      // Accent light — site steel blue
      const accent = new THREE.PointLight(0x6496c8, 0.4, 10);
      accent.position.set(0,3,-2); scene.add(accent);

      // Mouse drag
      let isDragging=false, prevMX=0, prevMY=0, velX=0, velY=0;
      const onDown = (e) => { isDragging=true; prevMX=e.clientX; prevMY=e.clientY; velX=0; velY=0; el.style.cursor="grabbing"; };
      const onMove = (e) => {
        if(!isDragging) return;
        const dx=e.clientX-prevMX, dy=e.clientY-prevMY;
        velX=dx*0.005; velY=dy*0.005;
        globe.rotation.y+=velX; globe.rotation.x+=velY;
        globe.rotation.x=Math.max(-Math.PI/2,Math.min(Math.PI/2,globe.rotation.x));
        prevMX=e.clientX; prevMY=e.clientY;
      };
      const onUp = () => { isDragging=false; el.style.cursor="grab"; };
      const onTStart = (e) => { isDragging=true; prevMX=e.touches[0].clientX; prevMY=e.touches[0].clientY; velX=0; velY=0; };
      const onTMove = (e) => {
        if(!isDragging) return;
        const dx=e.touches[0].clientX-prevMX, dy=e.touches[0].clientY-prevMY;
        velX=dx*0.005; velY=dy*0.005;
        globe.rotation.y+=velX; globe.rotation.x+=velY;
        globe.rotation.x=Math.max(-Math.PI/2,Math.min(Math.PI/2,globe.rotation.x));
        prevMX=e.touches[0].clientX; prevMY=e.touches[0].clientY;
      };
      const onTEnd = () => { isDragging=false; };
      el.style.cursor="grab";
      el.addEventListener("mousedown",onDown);
      window.addEventListener("mousemove",onMove);
      window.addEventListener("mouseup",onUp);
      el.addEventListener("touchstart",onTStart,{passive:true});
      window.addEventListener("touchmove",onTMove,{passive:true});
      window.addEventListener("touchend",onTEnd);

      const onResize = () => {
        camera.aspect=el.offsetWidth/el.offsetHeight;
        camera.updateProjectionMatrix();
        renderer.setSize(el.offsetWidth,el.offsetHeight);
      };
      window.addEventListener("resize",onResize);

      let t=0;
      const animate = () => {
        raf=requestAnimationFrame(animate);
        t+=0.005;

        if(!isDragging){
          velX*=0.95; velY*=0.95;
          globe.rotation.y+=velX; globe.rotation.x+=velY;
          if(Math.abs(velX)<0.0003) globe.rotation.y+=0.0007;
        }
        globe.rotation.x=Math.max(-Math.PI/2,Math.min(Math.PI/2,globe.rotation.x));

        // City pulses follow globe
        cityObjs.forEach(({pos, dot, ring1, ring2, phase, isMajor})=>{
          const rp = pos.clone().applyEuler(globe.rotation);
          dot.position.copy(rp);
          ring1.position.copy(rp); ring1.lookAt(new THREE.Vector3(0,0,0));
          if (ring2) { ring2.position.copy(rp); ring2.lookAt(new THREE.Vector3(0,0,0)); }

          // Face-camera visibility: nodes facing camera are brighter
          const facingFactor = Math.max(0, rp.clone().normalize().dot(new THREE.Vector3(0,0,1)));
          const pulse = Math.abs(Math.sin(t*2.5+phase));

          dot.material.opacity = 0.4 + facingFactor * 0.6;
          ring1.scale.setScalar(1 + 0.8*pulse);
          ring1.material.opacity = facingFactor * (0.15 + 0.45*pulse);

          if (ring2) {
            // Outer ring pulses slower, offset phase
            const pulse2 = Math.abs(Math.sin(t*1.8 + phase + 1));
            ring2.scale.setScalar(1 + 1.2*pulse2);
            ring2.material.opacity = facingFactor * (0.08 + 0.18*pulse2);
          }
        });

        // Arc animations
        arcs.forEach((arc)=>{
          arc.progress+=arc.speed;
          if(arc.progress>1.25) arc.progress=-0.05;
          const p=Math.max(0,Math.min(1,arc.progress));
          const N=arc.pts.length;
          const visN=Math.floor(p*N);
          const rPts=arc.pts.map(pt=>pt.clone().applyEuler(globe.rotation));

          if(visN>=2){
            arc.lineGeo.setFromPoints(rPts.slice(0,visN));
            const fi=p<0.08?p/0.08:1, fo=p>0.88?(1-p)/0.12:1;
            arc.lineMat.opacity=0.75*fi*fo;
          } else { arc.lineMat.opacity=0; }

          if(p>0.01&&p<0.99){
            const hi=Math.min(Math.floor(p*N),N-1);
            arc.sprite.position.copy(rPts[hi]);
            arc.spriteMat.opacity=arc.lineMat.opacity>0?1:0;
          } else { arc.spriteMat.opacity=0; }

          arc.trail.forEach(({mesh,mat},j)=>{
            const tp=p-(j+1)*0.02;
            if(tp>0&&tp<1&&arc.lineMat.opacity>0){
              mesh.position.copy(rPts[Math.min(Math.floor(tp*N),N-1)]);
              mat.opacity=(1-j/arc.trail.length)*0.6;
            } else { mat.opacity=0; }
          });
        });

        renderer.render(scene,camera);
      };
      animate();
      setReady(true);

      cleanupFn=()=>{
        el.removeEventListener("mousedown",onDown);
        window.removeEventListener("mousemove",onMove);
        window.removeEventListener("mouseup",onUp);
        el.removeEventListener("touchstart",onTStart);
        window.removeEventListener("touchmove",onTMove);
        window.removeEventListener("touchend",onTEnd);
        window.removeEventListener("resize",onResize);
        cancelAnimationFrame(raf);
        renderer.dispose();
        if(el.contains(renderer.domElement)) el.removeChild(renderer.domElement);
      };
    };

    init();
    return ()=>{ if(cleanupFn) cleanupFn(); };
  }, []);

  return (
    <div ref={mountRef} className="hero-globe-wrap" style={{
      position:"absolute",
      left:"52%",
      top:"50%",
      transform:"translateY(-50%)",
      width:"min(46vw, 580px)",
      height:"min(46vw, 580px)",
      zIndex:3,
      overflow:"visible",
      opacity: ready?1:0, transition:"opacity 1.2s ease 0.5s",
    }}/>
  );
}
